package cn.haiduo;
import cn.haiduo.finance.ProfitConfirmations;
import cn.haiduo.finance.Profit;
import cn.haiduo.inventory.InventoryService;
import cn.haiduo.orders.CsvOrders;
import cn.haiduo.fulfillment.TrackingEvents;
import java.util.*;
import java.time.Instant;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import org.springframework.transaction.support.TransactionTemplate;
import org.flywaydb.core.Flyway;
import org.testcontainers.postgresql.PostgreSQLContainer;
@org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable(named="RUN_SYNC_TESTS",matches="true")
class TrackingSnapshotContainerTest {
 static PostgreSQLContainer pg;static JdbcTemplate db;static TransactionTemplate tx;UUID tenant,order,shipment;
 @BeforeAll static void start(){pg=new PostgreSQLContainer("postgres:17.6");pg.start();var ds=new DriverManagerDataSource(pg.getJdbcUrl(),pg.getUsername(),pg.getPassword());Flyway.configure().dataSource(ds).load().migrate();db=new JdbcTemplate(ds);tx=new TransactionTemplate(new DataSourceTransactionManager(ds));}
 @AfterAll static void stop(){pg.stop();}
 @BeforeEach void setup(){tenant=UUID.randomUUID();order=UUID.randomUUID();shipment=UUID.randomUUID();db.update("insert into tenant values(?,'tracking')",tenant);db.update("insert into warehouse values(?,?::uuid,'default')",tenant,"00000000-0000-0000-0000-000000000001");db.update("insert into store values(?,?,'test','MOCK','MOCK')",UUID.randomUUID(),tenant);db.update("insert into sales_order(id,tenant_id,store,external_id,net,rate,currency,rate_source,rate_at) values(?,?,'test',?,100,7.2,'USD','confirmed',now())",order,tenant,order.toString());db.update("insert into shipment(id,tenant_id,order_id,carrier,tracking_number) values(?,?,?,'manual','test')",shipment,tenant,order);}
 @Test void duplicateTenTimesAndOldEventsNeverRegress(){var events=new TrackingEvents(db);UUID key=UUID.randomUUID();Instant time=Instant.parse("2026-01-01T00:00:00Z");for(int i=0;i<10;i++)tx.executeWithoutResult(s->events.accept(tenant,shipment,key,2,"DELIVERED",time,"test"));tx.executeWithoutResult(s->events.accept(tenant,shipment,UUID.randomUUID(),1,"IN_TRANSIT",time,"test"));tx.executeWithoutResult(s->events.accept(tenant,shipment,UUID.randomUUID(),3,"EXCEPTION",time,"test"));assertEquals("DELIVERED",db.queryForObject("select delivery_status from shipment where id=?",String.class,shipment));assertEquals(3,db.queryForObject("select count(*) from shipment_event where tenant_id=?",Integer.class,tenant));assertEquals(1,db.queryForObject("select count(*) from audit_log where tenant_id=?",Integer.class,tenant));assertThrows(org.springframework.web.server.ResponseStatusException.class,()->tx.execute(s->events.accept(UUID.randomUUID(),shipment,key,2,"DELIVERED",time,"test")));}
 @Test void multiLineCsvReservesAtomicallyAndDeduplicates(){UUID x=UUID.randomUUID(),y=UUID.randomUUID();for(UUID sku:List.of(x,y)){db.update("insert into product(id,tenant_id,name) values(?,?,'test')",sku,tenant);db.update("insert into sku values(?,?,?,'test',1,?)",sku,tenant,sku.toString(),sku);db.update("insert into inventory(tenant_id,sku_id,on_hand,reserved) values(?,?,?,0)",tenant,sku,sku.equals(x)?5:0);}String csv="store,order_no,sku,quantity,net,currency,rate\ntest,multi,"+x+",1,100,USD,7.2\ntest,multi,"+y+",1,100,USD,7.2";var imports=new CsvOrders(db);for(int i=0;i<10;i++)tx.executeWithoutResult(s->imports.importOrders(tenant,UUID.fromString("00000000-0000-0000-0000-000000000001"),csv,"test"));assertEquals(2,db.queryForObject("select count(*) from exchange_rate_snapshot where tenant_id=?",Integer.class,tenant));UUID imported=db.queryForObject("select id from sales_order where tenant_id=? and external_id='multi'",UUID.class,tenant);assertEquals(2,db.queryForObject("select count(*) from order_item where tenant_id=? and order_id=?",Integer.class,tenant,imported));assertThrows(IllegalStateException.class,()->tx.executeWithoutResult(s->new InventoryService(db).transition(tenant,imported,"reserve")));assertEquals(0,db.queryForObject("select sum(reserved) from inventory where tenant_id=?",Integer.class,tenant));db.update("update inventory set on_hand=5 where tenant_id=?",tenant);tx.executeWithoutResult(s->new InventoryService(db).transition(tenant,imported,"reserve"));assertEquals(2,db.queryForObject("select sum(reserved) from inventory where tenant_id=?",Integer.class,tenant));}
 @Test void confirmedActualProfitIsImmutableAndIdempotent(){UUID sku=UUID.randomUUID();db.update("insert into product(id,tenant_id,name) values(?,?,'profit')",sku,tenant);db.update("insert into sku values(?,?,?,'profit',200,?)",sku,tenant,sku.toString(),sku);db.update("insert into order_item(tenant_id,order_id,sku_id,quantity,unit_cost_cny) values(?,?,?,1,200)",tenant,order,sku);db.update("update sales_order set status='SHIPPED',payment_status='PAID' where id=?",order);db.update("insert into order_fee(tenant_id,order_id,kind,amount_cny,original_amount,currency,exchange_rate,rate_source,effective_at) values(?,?,'FREIGHT',50,50,'CNY',1,'confirmed',now()),(?,?,'PLATFORM',72,72,'CNY',1,'confirmed',now())",tenant,order,tenant,order);var service=new ProfitConfirmations(db);UUID key=UUID.randomUUID();for(int i=0;i<10;i++)tx.executeWithoutResult(s->service.confirm(tenant,order,key,"receipts checked","finance"));assertEquals(1,db.queryForObject("select count(*) from profit_confirmation where tenant_id=?",Integer.class,tenant));assertEquals("398.00",db.queryForObject("select contribution_cny::text from profit_confirmation where tenant_id=?",String.class,tenant));db.update("update order_fee set amount_cny=60 where tenant_id=? and kind='FREIGHT'",tenant);assertEquals("398.00",db.queryForObject("select contribution_cny::text from profit_confirmation where tenant_id=?",String.class,tenant));assertThrows(org.springframework.dao.DataAccessException.class,()->db.update("update profit_confirmation set contribution_cny=1 where tenant_id=?",tenant));assertThrows(org.springframework.web.server.ResponseStatusException.class,()->tx.execute(s->service.confirm(UUID.randomUUID(),order,key,"receipts checked","finance")));}
 @Test void snapshotCannotBeEditedAndNewVersionDoesNotRewriteOld(){UUID original=db.queryForObject("select exchange_rate_snapshot_id from sales_order where id=?",UUID.class,order);assertThrows(org.springframework.dao.DataAccessException.class,()->db.update("update exchange_rate_snapshot set rate=8 where id=?",original));assertThrows(org.springframework.dao.DataAccessException.class,()->db.update("delete from exchange_rate_snapshot where id=?",original));db.update("update sales_order set rate=8 where id=?",order);assertNotEquals(original,db.queryForObject("select exchange_rate_snapshot_id from sales_order where id=?",UUID.class,order));assertEquals("7.20000000",db.queryForObject("select rate::text from exchange_rate_snapshot where id=?",String.class,original));}
}
